54	// ── POST /v1/notifications/register ───────────────────────────────────────────
55	
56	#[derive(Deserialize)]
57	#[serde(rename_all = "camelCase")]
58	pub struct RegisterRequest {
59	    /// App-generated stable device identifier. Survives DID promotion, unlike `devices.id`.
60	    pub device_uuid: String,
61	    /// The device's P-256 notification `did:key`. Payloads are sealed to this.
62	    pub notification_public_key: String,
63	    pub apns_token: String,
64	    pub apns_topic: String,
65	}
66	
67	#[derive(Serialize)]
68	#[serde(rename_all = "camelCase")]
69	pub struct RegisterResponse {
70	    /// Always `"pending"`: the row is stored, and the relay handle is being minted in the
71	    /// background. The app learns the outcome by re-reading, not by blocking here.
72	    pub status: &'static str,
73	}
74	
75	pub async fn register_notifications(
76	    State(state): State<AppState>,
77	    method: Method,
78	    uri: Uri,
79	    headers: HeaderMap,
80	    Json(payload): Json<RegisterRequest>,
81	) -> Result<Json<RegisterResponse>, ApiError> {
82	    let user = authenticate_access(&headers, &method, &uri, &state)?;
83	    require_notifications_enabled(&state)?;
84	
85	    if payload.device_uuid.is_empty() || payload.device_uuid.len() > MAX_DEVICE_UUID_LEN {
86	        return Err(ApiError::new(
87	            ErrorCode::InvalidRequest,
88	            "deviceUuid must be between 1 and 128 characters",
89	        ));
90	    }
91	    validate_registration_fields(
92	        &payload.notification_public_key,
93	        &payload.apns_token,
94	        &payload.apns_topic,
95	    )?;
96	
97	    store::upsert_registration(
98	        &state.db,
99	        &user.did,
100	        &payload.device_uuid,
101	        &payload.notification_public_key,
102	        &payload.apns_token,
103	        &payload.apns_topic,
104	    )
105	    .await
106	    .map_err(|e| {
107	        tracing::error!(error = %e, "failed to store a notification registration");
108	        ApiError::new(ErrorCode::InternalError, "failed to store the registration")
109	    })?;
110	
111	    if let Some(sender) = state.notify_sender.as_ref() {
112	        sender.send(NotifyJob::RegisterHandle {
113	            owner: RegistrationOwner::Account {
114	                did: user.did.clone(),
115	                device_uuid: payload.device_uuid.clone(),
116	            },
117	            apns_token: payload.apns_token,
118	            apns_topic: payload.apns_topic,
119	        });
120	    }
121	
122	    Ok(Json(RegisterResponse { status: "pending" }))
123	}
124	
125	const MAX_DEVICE_UUID_LEN: usize = 128;
126	
127	// ── DELETE /v1/notifications/register/{deviceUuid} ────────────────────────────
128	
129	#[derive(Serialize)]
130	#[serde(rename_all = "camelCase")]
131	pub struct UnregisterResponse {
132	    /// `"deleted"` when a registration existed, `"absent"` when there was nothing to remove.
133	    pub status: &'static str,
134	}
135	
136	pub async fn unregister_notifications(
137	    State(state): State<AppState>,
138	    method: Method,
139	    uri: Uri,
140	    headers: HeaderMap,
141	    Path(device_uuid): Path<String>,
142	) -> Result<Json<UnregisterResponse>, ApiError> {
143	    let user = authenticate_access(&headers, &method, &uri, &state)?;
144	
145	    // Deliberately *not* gated on `require_notifications_enabled`, unlike register and
146	    // sender-keys. An operator who removes the relay config leaves registrations behind; the
147	    // one thing a device should still be able to do is disown its own row and have the relay
148	    // told to drop the handle. Gating this would strand exactly the rows most worth removing.
149	
150	    // Read the row before deleting so the relay handle can be dropped too — otherwise the
151	    // relay keeps forwarding to a device this account has explicitly disowned.
152	    let handle = store::list_registrations(&state.db, &user.did)
153	        .await
154	        .ok()
155	        .and_then(|rows| {
156	            rows.into_iter()
157	                .find(|r| r.device_id == device_uuid)
158	                .and_then(|r| r.push_handle)
159	        });
160	
161	    let existed = store::delete_registration(&state.db, &user.did, &device_uuid)
162	        .await
163	        .map_err(|e| {
164	            tracing::error!(error = %e, "failed to delete a notification registration");
165	            ApiError::new(
166	                ErrorCode::InternalError,
167	                "failed to delete the registration",
168	            )
169	        })?;
170	
171	    if let (Some(handle), Some(sender)) = (handle, state.notify_sender.as_ref()) {
172	        sender.send(NotifyJob::DropHandle { handle });
173	    }
174	
175	    Ok(Json(UnregisterResponse {
176	        // Idempotent: repeating a delete is a 200, not a 404. The app retries this on a flaky
177	        // network and must not have to distinguish "already gone" from "failed".
178	        status: if existed { "deleted" } else { "absent" },
179	    }))
180	}
181	
182	// ── GET /v1/notifications/sender-keys ─────────────────────────────────────────
183	
184	/// The account-holder's re-pin surface. The published set itself is built by
185	/// [`notification_views::sender_keys_response`], which the operator surface shares — the
186	/// sender keys belong to the instance, not to whoever is asking.
187	pub async fn get_sender_keys(
188	    State(state): State<AppState>,
189	    method: Method,
190	    uri: Uri,
191	    headers: HeaderMap,
192	) -> Result<Json<SenderKeysResponse>, ApiError> {
193	    authenticate_access(&headers, &method, &uri, &state)?;
194	    require_notifications_enabled(&state)?;
195	    Ok(Json(sender_keys_response(&state).await?))
196	}
