219	    async fn seed_account(state: &AppState, did: &str) {
220	        sqlx::query(
221	            "INSERT INTO accounts (did, email, password_hash, created_at, updated_at) \
222	             VALUES (?, 'notif@example.com', 'hash', datetime('now'), datetime('now'))",
223	        )
224	        .bind(did)
