230	    /// A full-access HS256 access token, the shape `authenticate_access` verifies.
231	    fn token(state: &AppState, did: &str) -> String {
232	        #[derive(serde::Serialize)]
233	        struct Claims {
234	            sub: String,
235	            aud: String,
236	            exp: u64,
237	            scope: String,
238	        }
239	        let claims = Claims {
240	            sub: did.to_string(),
241	            aud: "did:plc:test".to_string(),
242	            exp: (chrono::Utc::now().timestamp() + 3600) as u64,
243	            scope: "com.atproto.access".to_string(),
244	        };
245	        jsonwebtoken::encode(
246	            &jsonwebtoken::Header::new(jsonwebtoken::Algorithm::HS256),
247	            &claims,
248	            &jsonwebtoken::EncodingKey::from_secret(&state.jwt_secret),
249	        )
250	        .unwrap()
251	    }
252	
253	    async fn call(state: AppState, request: Request<Body>) -> (StatusCode, Value) {
254	        let response = build_router(state)
255	            .oneshot(request)
256	            .await
257	            .expect("response");
258	        let status = response.status();
259	        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
260	            .await
261	            .expect("body");
262	        let value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
263	        (status, value)
264	    }
265	
266	    fn device_key() -> String {
267	        crypto::generate_p256_keypair().unwrap().key_id.0
268	    }
269	
270	    fn register_body(device_uuid: &str, key: &str) -> Value {
271	        json!({
272	            "deviceUuid": device_uuid,
273	            "notificationPublicKey": key,
274	            "apnsToken": "abcdef0123456789",
275	            "apnsTopic": "org.obsign.identitywallet",
276	        })
277	    }
