279	    async fn register(state: AppState, did: &str, body: Value) -> (StatusCode, Value) {
280	        let auth = format!("Bearer {}", token(&state, did));
281	        call(
282	            state,
283	            Request::post("/v1/notifications/register")
284	                .header("authorization", auth)
285	                .header("content-type", "application/json")
286	                .body(Body::from(body.to_string()))
287	                .unwrap(),
288	        )
289	        .await
290	    }
