403	    #[tokio::test]
404	    async fn unregistering_is_idempotent() {
405	        let state = state_with_notifications().await;
406	        seed_account(&state, "did:plc:notifroutes").await;
407	        register(
408	            state.clone(),
409	            "did:plc:notifroutes",
410	            register_body("device-1", &device_key()),
411	        )
412	        .await;
413	
414	        let delete = |state: AppState| async move {
415	            let auth = format!("Bearer {}", token(&state, "did:plc:notifroutes"));
416	            call(
417	                state,
418	                Request::delete("/v1/notifications/register/device-1")
