475	    /// The re-pin contract, over the wire: a retired key is still published, a revoked one is
476	    /// not, and the newest active key leads.
477	    #[tokio::test]
478	    async fn sender_keys_publishes_active_and_retired_but_never_revoked() {
479	        let state = state_with_notifications().await;
480	        seed_account(&state, "did:plc:notifroutes").await;
481	
482	        let master = [0x7u8; 32];
483	        let retired = crate::notifications::generate_sender_key(&state, &master)
484	            .await
485	            .unwrap()
486	            .0;
487	        let revoked = crate::notifications::generate_sender_key(&state, &master)
488	            .await
489	            .unwrap()
490	            .0;
491	        let active = crate::notifications::generate_sender_key(&state, &master)
492	            .await
493	            .unwrap()
494	            .0;
495	        store::retire_sender_key(&state.db, retired).await.unwrap();
496	        store::revoke_sender_key(&state.db, revoked).await.unwrap();
497	
498	        let auth = format!("Bearer {}", token(&state, "did:plc:notifroutes"));
499	        let (status, body) = call(
500	            state.clone(),
501	            Request::get("/v1/notifications/sender-keys")
502	                .header("authorization", auth)
503	                .body(Body::empty())
504	                .unwrap(),
505	        )
506	        .await;
507	        assert_eq!(status, StatusCode::OK, "{body}");
508	
509	        let kids: Vec<i64> = body["keys"]
510	            .as_array()
511	            .unwrap()
512	            .iter()
513	            .map(|k| k["kid"].as_i64().unwrap())
514	            .collect();
515	        assert_eq!(
516	            kids,
517	            vec![active, retired],
518	            "revoked must be gone; retired must remain"
519	        );
520	
521	        // Every published key is a usable P-256 did:key, not an opaque string.
522	        for key in body["keys"].as_array().unwrap() {
523	            crypto::p256_public_key_from_did_key(key["publicKey"].as_str().unwrap())
524	                .expect("published key must decode");
525	        }
526	    }
