528	    /// A relay configured without a master key cannot mint or unwrap sender keys. It must say
529	    /// so, rather than answer 200 with an empty set — a client that pinned nothing would then
530	    /// fail to verify every notification it received, with no way to tell why.
531	    #[tokio::test]
532	    async fn a_configured_instance_without_a_master_key_refuses_to_publish_an_empty_set() {
533	        let mut state = state_with_notifications().await;
534	        let mut config = (*state.config).clone();
535	        config.signing_key_master_key = None;
536	        state.config = Arc::new(config);
537	        seed_account(&state, "did:plc:notifroutes").await;
538	
539	        let auth = format!("Bearer {}", token(&state, "did:plc:notifroutes"));
540	        let (status, body) = call(
541	            state.clone(),
542	            Request::get("/v1/notifications/sender-keys")
543	                .header("authorization", auth)
544	                .body(Body::empty())
545	                .unwrap(),
546	        )
547	        .await;
548	
549	        // 503, not the 501 an unconfigured instance returns: the operator *has* opted in, the
550	        // instance simply cannot serve the keys right now.
551	        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{body}");
552	        assert!(
553	            body["error"]["message"]
554	                .as_str()
555	                .unwrap_or_default()
556	                .contains("master key"),
557	            "the error must name the missing master key: {body}"
558	        );
559	    }
560	
561	    /// The other route to an empty set: the master key is present, but the stored key material
562	    /// will not decrypt under it (a restored backup wrapped under a previous KEK, say). The
563	    /// client must be told, not handed an empty array it would pin as authoritative.
564	    #[tokio::test]
565	    async fn a_stored_key_that_will_not_unwrap_is_reported_rather_than_silently_dropped() {
566	        let state = state_with_notifications().await;
567	        seed_account(&state, "did:plc:notifroutes").await;
568	
569	        // Ciphertext that is well-formed base64 but not decryptable under this master key —
570	        // exactly what a KEK mismatch leaves behind.
571	        store::insert_sender_key(&state.db, "bm90LWEtcmVhbC1jaXBoZXJ0ZXh0LWF0LWFsbA")
572	            .await
573	            .unwrap();
574	
575	        let auth = format!("Bearer {}", token(&state, "did:plc:notifroutes"));
576	        let (status, body) = call(
577	            state.clone(),
578	            Request::get("/v1/notifications/sender-keys")
579	                .header("authorization", auth)
