3	//! The pds's first *outbound* iroh leg. Everything else in `iroh_tunnel.rs` accepts; this
4	//! dials the configured notification relay on the `ezpds/notify/0` ALPN. It reuses that same
5	//! bound `Endpoint` — an iroh endpoint both accepts and dials, so the instance presents one
6	//! stable node identity to the relay, which is the identity the relay authorizes against
7	//! (`connection.remote_id()`; no credential ever travels in a message).
8	//!
9	//! Framing mirrors the relay's accept side: one JSON request per bidirectional stream,
10	//! delimited by our FIN, one JSON response back, under a per-stream deadline.
11	//!
12	//! Connections are lazy and cached, with a one-shot re-dial retry: the expected failure is a
13	//! *stale* connection after a relay restart. Enrollment is likewise not a startup step — the
14	//! client enrolls when the relay answers `notEnrolled`, so a relay restarted, re-provisioned,
15	//! or reached for the first time mid-run heals by itself. A relay that is down must never
16	//! become a pds outage, so every failure here is logged and swallowed by the caller
17	//! (`crate::notifications`), never propagated into a request path.
18	//!
19	//! The second half of the file is the fire-and-forget send worker: trigger sites enqueue
20	//! `NotifyJob`s onto an unbounded in-process mpsc (`NotifySender`) and return immediately.
21	//! The worker drains jobs sequentially, writes relay handles back to the registration rows,
22	//! and prunes a registration the relay reports `unregistered` (APNs 410).
23	
24	use std::sync::Arc;
25	use std::time::Duration;
26	
27	use iroh::{Endpoint, EndpointAddr, EndpointId};
28	use notify_relay::protocol::{Request, Response, ALPN, MAX_MESSAGE_LEN};
29	use tokio::sync::Mutex;
30	
31	/// Maximum time for one request/response exchange, matching the relay's own stream deadline.
32	const STREAM_TIMEOUT: Duration = Duration::from_secs(30);
33	
34	/// How long a dial may take before we give up and let the next send retry.
35	const DIAL_TIMEOUT: Duration = Duration::from_secs(15);
36	
37	/// A dialing client for one configured relay.
38	pub struct NotifyRelayClient {
39	    endpoint: Endpoint,
40	    /// Where to dial. Built from the configured node id alone, so reaching the relay depends
41	    /// on iroh discovery + holepunching rather than on the operator knowing an address —
42	    /// which is the point of naming a relay by node id in the first place.
43	    relay_addr: EndpointAddr,
44	    /// The claim code from `[notifications] enrollment_code`, presented on every `enroll`.
45	    /// The relay consumes it once; later enrolls of an already-enrolled node succeed anyway,
46	    /// so re-presenting a spent code is harmless.
47	    enrollment_code: Option<String>,
48	    /// The live connection, if any. Behind an async mutex because establishing one is an
49	    /// `await`: without serializing, a burst of sends after a relay restart would each dial
50	    /// their own connection.
51	    connection: Mutex<Option<iroh::endpoint::Connection>>,
52	}
53	
54	impl NotifyRelayClient {
55	    /// Build a client for `relay_node_id`, dialing from the pds's own endpoint.
56	    ///
57	    /// Fails only if the configured node id is unparseable — a config error worth surfacing
58	    /// at startup rather than as a silent non-delivery later.
59	    pub fn new(
60	        endpoint: Endpoint,
61	        relay_node_id: &str,
62	        enrollment_code: Option<String>,
63	    ) -> anyhow::Result<Self> {
64	        let relay_id: EndpointId = relay_node_id
65	            .parse()
66	            .map_err(|e| anyhow::anyhow!("notifications.relay is not a valid iroh node id: {e}"))?;
67	        Ok(Self::with_addr(
68	            endpoint,
69	            EndpointAddr::new(relay_id),
70	            enrollment_code,
71	        ))
72	    }
73	
74	    /// Build a client for a relay at a known address, skipping discovery.
75	    ///
76	    /// The loopback end-to-end test dials a relay bound on 127.0.0.1 with iroh's `Minimal`
77	    /// preset, which has no discovery to resolve a bare node id against.
78	    pub fn with_addr(
79	        endpoint: Endpoint,
80	        relay_addr: EndpointAddr,
81	        enrollment_code: Option<String>,
82	    ) -> Self {
83	        Self {
84	            endpoint,
85	            relay_addr,
86	            enrollment_code,
87	            connection: Mutex::new(None),
88	        }
89	    }
90	
91	    /// Send one request and await its response, dialing (and enrolling) as needed.
92	    pub async fn call(&self, request: Request) -> anyhow::Result<Response> {
93	        let response = self.exchange(request.clone()).await?;
94	
95	        // Enrollment is not a startup step: the relay may have been restarted, re-provisioned,
96	        // or reached for the first time mid-run. Rather than tracking enrollment state we let
97	        // the relay tell us, and enroll exactly when it says we must. This is idempotent and
98	        // costs one extra round trip only on the first send after a relay forgets us.
99	        if matches!(response, Response::NotEnrolled) && !matches!(request, Request::Enroll { .. }) {
100	            let enrolled = self
101	                .exchange(Request::Enroll {
102	                    claim_code: self.enrollment_code.clone(),
103	                })
104	                .await?;
105	            if !matches!(enrolled, Response::Ok) {
106	                anyhow::bail!("relay refused enrollment: {enrolled:?}");
107	            }
108	            return self.exchange(request).await;
109	        }
110	
111	        Ok(response)
112	    }
113	
114	    /// One request/response exchange on a fresh stream over the cached connection.
115	    async fn exchange(&self, request: Request) -> anyhow::Result<Response> {
116	        let encoded = serde_json::to_vec(&request)?;
117	
118	        // One retry, because the failure we expect is a *stale* cached connection: the relay
119	        // restarted and our handle to it is dead, which only surfaces when we try to use it.
120	        // Retrying with a fresh dial turns that into a transparent reconnect. A second failure
121	        // is a real outage, and the caller drops the notification.
122	        let mut last_error = None;
123	        for attempt in 0..2 {
124	            let connection = match self.connect(attempt == 1).await {
125	                Ok(c) => c,
126	                Err(e) => {
127	                    last_error = Some(e);
128	                    continue;
129	                }
130	            };
131	            match Self::round_trip(&connection, &encoded).await {
132	                Ok(response) => return Ok(response),
133	                Err(e) => {
134	                    tracing::debug!(error = %e, attempt, "notify relay exchange failed");
135	                    // Drop the connection so the next attempt re-dials rather than reusing
136	                    // something we just proved broken.
137	                    *self.connection.lock().await = None;
138	                    last_error = Some(e);
139	                }
140	            }
141	        }
142	        Err(last_error.unwrap_or_else(|| anyhow::anyhow!("notify relay unreachable")))
143	    }
144	
145	    /// Return the cached connection, dialing a new one if absent (or if `force_redial`).
146	    async fn connect(&self, force_redial: bool) -> anyhow::Result<iroh::endpoint::Connection> {
147	        let mut guard = self.connection.lock().await;
148	        if force_redial {
149	            *guard = None;
150	        }
151	        if let Some(connection) = guard.as_ref() {
152	            return Ok(connection.clone());
153	        }
154	        let connection = tokio::time::timeout(
155	            DIAL_TIMEOUT,
156	            self.endpoint.connect(self.relay_addr.clone(), ALPN),
157	        )
158	        .await
159	        .map_err(|_| anyhow::anyhow!("dialing the notify relay timed out"))?
160	        .map_err(|e| anyhow::anyhow!("failed to dial the notify relay: {e}"))?;
161	        *guard = Some(connection.clone());
162	        Ok(connection)
163	    }
164	
165	    async fn round_trip(
166	        connection: &iroh::endpoint::Connection,
167	        encoded: &[u8],
168	    ) -> anyhow::Result<Response> {
169	        let exchange = async {
170	            let (mut send, mut recv) = connection.open_bi().await?;
171	            send.write_all(encoded).await?;
172	            // FIN is the frame delimiter: the relay reads to end, so without this it waits
173	            // forever and we time out against a perfectly healthy relay.
174	            send.finish()?;
175	            let bytes = recv.read_to_end(MAX_MESSAGE_LEN).await?;
176	            Ok::<Response, anyhow::Error>(serde_json::from_slice(&bytes)?)
177	        };
178	        tokio::time::timeout(STREAM_TIMEOUT, exchange)
179	            .await
180	            .map_err(|_| anyhow::anyhow!("notify relay exchange timed out"))?
181	    }
182	}
183	
184	// ── The send worker ───────────────────────────────────────────────────────────
185	//
186	// Triggers must never wait on the relay: a claim ceremony that hangs because a push relay is
187	// slow has traded a missed banner for a broken request. So callers hand work to an unbounded
188	// in-process queue and return immediately.
189	//
190	// The queue is in-memory only, deliberately. A missed push is a missed *banner*, not lost
191	// data — the app reconciles state from Custos on next contact — so durable queuing would add
192	// a table, a sweep, and a retry policy to protect something that is already recoverable.
193	
194	/// One unit of work for the relay worker.
195	#[derive(Debug)]
196	pub enum NotifyJob {
197	    /// Register (or re-register) a device's APNs token, recording the handle we get back.
198	    RegisterHandle {
199	        owner: RegistrationOwner,
200	        apns_token: String,
201	        apns_topic: String,
202	    },
203	    /// Forget a handle at the relay. Best effort: a handle we fail to drop expires with the
204	    /// device token rather than lingering forever.
205	    DropHandle { handle: String },
206	    /// Deliver one sealed payload.
207	    Push {
208	        owner: RegistrationOwner,
209	        handle: String,
210	        kid: i64,
211	        enc: String,
212	        ct: String,
213	    },
214	}
215	
216	/// Which registration table a job's row lives in — the two surfaces are keyed differently, so
217	/// the worker needs to know which one to write a handle back to (or prune on a dead token).
218	#[derive(Debug, Clone, PartialEq, Eq)]
219	pub enum RegistrationOwner {
220	    /// A wallet account's device: `(did, device_uuid)`.
221	    Account { did: String, device_uuid: String },
222	    /// An admin-companion device, keyed by `admin_devices.id`.
223	    AdminDevice { admin_device_id: String },
224	}
225	
226	/// The sender half handed to trigger sites, paired with the queue's depth counter. Cloning is
227	/// cheap; dropping every clone stops the worker.
228	///
229	/// The depth exists because the queue is unbounded: a relay outage cannot break a request path,
230	/// but it *can* grow this queue for as long as it lasts, and before this counter that growth was
231	/// only inferable from `warn!` volume. It is carried here rather than sampled from the receiver's
232	/// `len()` because the receiver is moved into the worker task, out of reach of the operator
233	/// health endpoint that reports the same number as JSON.
234	#[derive(Clone)]
235	pub struct NotifySender {
236	    tx: tokio::sync::mpsc::UnboundedSender<NotifyJob>,
237	    depth: Arc<QueueDepth>,
238	}
239	
240	/// The queue's depth counter and its gauge, held separately from the sender so the worker can
241	/// decrement without owning a `tx` clone — a sender inside the worker task would keep the
242	/// channel open forever, and `rx.recv()` would never report the queue closed.
243	struct QueueDepth {
244	    /// Jobs enqueued but not yet finished. Signed so a pairing bug reads as a negative rather
245	    /// than wrapping into an astronomical unsigned value on a dashboard.
246	    count: std::sync::atomic::AtomicI64,
247	    metrics: Arc<crate::metrics::Metrics>,
248	}
249	
250	impl QueueDepth {
251	    /// Apply a delta and publish the result to the gauge.
252	    fn bump(&self, delta: i64) {
253	        let depth = self
254	            .count
255	            .fetch_add(delta, std::sync::atomic::Ordering::Relaxed)
256	            + delta;
257	        self.metrics
258	            .notify_queue_depth
259	            .record(depth.max(0) as u64, &[]);
260	    }
261	}
262	
263	impl NotifySender {
264	    /// Enqueue one job.
265	    ///
266	    /// Infallible from a caller's perspective: the only failure is a stopped worker, and every
267	    /// trigger site treats delivery as best effort — they all discarded the old `Result`
268	    /// identically. Handling it here means a dropped job is logged once instead of being
269	    /// silently swallowed at five call sites.
270	    pub fn send(&self, job: NotifyJob) {
271	        // Increment first: a job counted only after a successful send could be drained and
272	        // decremented before it was ever added, driving the depth negative under load.
273	        self.depth.bump(1);
274	        if self.tx.send(job).is_err() {
275	            // A rejected job never entered the queue, so it must not read as outstanding —
276	            // otherwise a stopped worker would look like a permanently growing backlog.
277	            self.depth.bump(-1);
278	            tracing::warn!("dropped a notification job: the relay worker is not running");
279	        }
280	    }
281	
282	    /// Jobs outstanding right now. Read by `GET /v1/admin/health`, which works with
283	    /// `[telemetry] metrics_enabled` off — the same reason `sweep_status.rs` mirrors its gauges.
284	    pub fn depth(&self) -> i64 {
285	        self.depth.count.load(std::sync::atomic::Ordering::Relaxed)
286	    }
287	}
288	
289	/// Spawn the worker that drains the queue against `client`.
290	///
291	/// Jobs run sequentially. That is intentional: the relay rate-limits per node, and the
292	/// volume here is device-count-scaled, not user-traffic-scaled. Sequential also means one
293	/// slow push delays the next rather than opening a connection storm at a struggling relay.
294	pub fn spawn_worker(
295	    client: Arc<NotifyRelayClient>,
296	    db: sqlx::SqlitePool,
297	    metrics: Arc<crate::metrics::Metrics>,
298	) -> (NotifySender, tokio::task::JoinHandle<()>) {
299	    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<NotifyJob>();
300	    let depth = Arc::new(QueueDepth {
301	        count: std::sync::atomic::AtomicI64::new(0),
302	        metrics,
303	    });
304	    let worker_depth = depth.clone();
305	    let handle = tokio::spawn(async move {
306	        while let Some(job) = rx.recv().await {
307	            if let Err(e) = run_job(&client, &db, job).await {
308	                // Every relay failure ends here. Notification delivery is best-effort by
309	                // design, so this is a log line, not an error path anyone recovers from.
310	                tracing::warn!(error = %e, "notify relay job failed");
311	            }
312	            // Decremented *after* the job runs, not at `recv`, so the depth counts outstanding
313	            // work rather than only what is waiting. During the outage this metric exists for,
314	            // each job burns the full 30s stream timeout — a single stuck job is real backlog,
315	            // and a depth that read 0 through it would be reporting the wrong thing.
316	            worker_depth.bump(-1);
317	        }
318	        tracing::info!("notify relay worker stopped (queue closed)");
319	    });
320	    (NotifySender { tx, depth }, handle)
321	}
322	
323	async fn run_job(
324	    client: &NotifyRelayClient,
325	    db: &sqlx::SqlitePool,
326	    job: NotifyJob,
327	) -> anyhow::Result<()> {
328	    use crate::db::notifications as store;
329	    use notify_relay::protocol::PushOutcome;
330	
331	    match job {
332	        NotifyJob::RegisterHandle {
333	            owner,
334	            apns_token,
335	            apns_topic,
336	        } => {
337	            let response = client
338	                .call(Request::RegisterHandle {
339	                    apns_token,
340	                    apns_topic,
341	                })
342	                .await?;
343	            let Response::Handle { handle } = response else {
344	                anyhow::bail!("relay refused handle registration: {response:?}");
345	            };
346	            match &owner {
347	                RegistrationOwner::Account { did, device_uuid } => {
348	                    store::set_registration_handle(db, did, device_uuid, &handle).await?;
349	                }
350	                RegistrationOwner::AdminDevice { admin_device_id } => {
351	                    store::set_admin_registration_handle(db, admin_device_id, &handle).await?;
352	                }
353	            }
354	        }
355	        NotifyJob::DropHandle { handle } => {
356	            client.call(Request::DropHandle { handle }).await?;
357	        }
358	        NotifyJob::Push {
359	            owner,
360	            handle,
361	            kid,
362	            enc,
363	            ct,
364	        } => {
365	            let response = client
366	                .call(Request::Push {
367	                    handle,
368	                    // `kid` is a positive INTEGER PRIMARY KEY; the wire carries it as u32,
369	                    // which is the same value for every kid an instance will ever mint.
370	                    kid: kid as u32,
371	                    enc,
372	                    ct,
373	                    priority: None,
374	                    ttl_secs: None,
375	                    ping: None,
376	                })
377	                .await?;
378	            match response {
379	                Response::Pushed {
380	                    outcome: PushOutcome::Unregistered,
381	                } => {
382	                    // APNs 410, relayed back to us: this device token is permanently dead
383	                    // (app deleted, or reinstalled with a new token). Prune at the moment of
384	                    // proof — the alternative is fanning out to a corpse forever.
385	                    prune(db, &owner).await?;
386	                    tracing::info!("pruned a notification registration the relay reported dead");
387	                }
388	                Response::Pushed {
389	                    outcome: PushOutcome::Delivered,
390	                } => {}
391	                other => {
392	                    // Throttled, tooLarge, apnsError, unknownHandle — all real outcomes, none
393	                    // of them recoverable here. Log the shape and drop the banner.
394	                    tracing::warn!(?other, "notify relay declined a push");
395	                }
396	            }
397	        }
398	    }
399	    Ok(())
400	}
401	
402	async fn prune(db: &sqlx::SqlitePool, owner: &RegistrationOwner) -> Result<(), sqlx::Error> {
403	    use crate::db::notifications as store;
404	    match owner {
405	        RegistrationOwner::Account { did, device_uuid } => {
406	            store::delete_registration(db, did, device_uuid).await?;
407	        }
408	        RegistrationOwner::AdminDevice { admin_device_id } => {
409	            store::delete_admin_registration(db, admin_device_id).await?;
410	        }
411	    }
412	    Ok(())
413	}
