420	    fn orphan_sender() -> NotifySender {
421	        let (tx, rx) = tokio::sync::mpsc::unbounded_channel::<NotifyJob>();
422	        // Held, not dropped: dropping the receiver would make every `send` fail.
423	        std::mem::forget(rx);
424	        NotifySender {
425	            tx,
426	            depth: Arc::new(QueueDepth {
427	                count: std::sync::atomic::AtomicI64::new(0),
428	                metrics: Arc::new(crate::metrics::Metrics::disabled()),
429	            }),
430	        }
431	    }
