437	
438	        for _ in 0..3 {
439	            sender.send(NotifyJob::DropHandle {
440	                handle: "h".to_owned(),
441	            });
442	        }
443	        assert_eq!(sender.depth(), 3);
444	
445	        // A clone shares the counter — trigger sites hold clones, and each must observe the
446	        // same queue rather than its own.
