450	    #[test]
451	    fn a_send_to_a_stopped_worker_does_not_inflate_the_depth() {
452	        let (tx, rx) = tokio::sync::mpsc::unbounded_channel::<NotifyJob>();
453	        drop(rx);
454	        let sender = NotifySender {
455	            tx,
456	            depth: Arc::new(QueueDepth {
457	                count: std::sync::atomic::AtomicI64::new(0),
458	                metrics: Arc::new(crate::metrics::Metrics::disabled()),
459	            }),
460	        };
461	
462	        sender.send(NotifyJob::DropHandle {
463	            handle: "h".to_owned(),
464	        });
465	        // A rejected job never entered the queue, so it must not be counted as outstanding —
466	        // otherwise a stopped worker would read as a permanently growing backlog.
