470	    #[tokio::test]
471	    async fn the_worker_decrements_the_depth_as_it_drains() {
472	        // No relay is reachable, so every job fails — which is exactly the outage case the
473	        // metric exists for, and the depth must still return to zero.
474	        //
475	        // The target is a bare node id with no address, under the `Minimal` preset's absent
476	        // discovery: the dial cannot resolve and fails immediately, rather than burning the
477	        // 15s DIAL_TIMEOUT twice.
478	        let unreachable = crate::iroh_tunnel::loopback_endpoint(false).await;
479	        let unreachable_id = unreachable.id();
480	        unreachable.close().await;
