39	/// The plaintext a device's Notification Service Extension decrypts and renders.
40	///
41	/// Serialized camelCase, matching the wallet's decoder. `pad` is the length-quantizing
42	/// filler; it is meaningless to the reader and is the last field so the arithmetic below can
43	/// reason about it as a suffix.
44	#[derive(Debug, Clone, Serialize)]
45	#[serde(rename_all = "camelCase")]
46	pub struct NotificationPayload {
47	    /// Machine-readable kind, e.g. `agent_claim_pending`. The app routes on this.
48	    #[serde(rename = "type")]
49	    pub kind: &'static str,
50	    pub title: String,
51	    pub body: String,
52	    #[serde(skip_serializing_if = "Option::is_none")]
53	    pub data: Option<serde_json::Value>,
54	    /// Spaces, sized so the serialized APNs body lands on a padding bucket.
55	    pub pad: String,
56	}
