58	impl NotificationPayload {
59	    /// A payload with no padding yet — [`seal_for`] computes and applies it.
60	    pub fn new(kind: &'static str, title: impl Into<String>, body: impl Into<String>) -> Self {
61	        Self {
62	            kind,
63	            title: title.into(),
64	            body: body.into(),
65	            data: None,
66	            pad: String::new(),
67	        }
68	    }
69	
70	    /// Attach structured routing data (a claim attempt id, a subject DID, …).
71	    pub fn with_data(mut self, data: serde_json::Value) -> Self {
72	        self.data = Some(data);
73	        self
74	    }
75	}
