77	/// Notify every device registered to `did`.
78	///
79	/// Silent and harmless when notifications are unconfigured, when the account has no
80	/// registered devices, or when the relay is unreachable. Returns how many sealed payloads
81	/// were enqueued toward the relay — delivery stays fire-and-forget beyond that, but "zero
82	/// devices could even be attempted" is a fact some triggers branch on (the consent push
83	/// makes number matching mandatory only when a push actually went out).
84	pub async fn notify_device(state: &AppState, did: &str, payload: NotificationPayload) -> usize {
85	    let Some(sender) = state.notify_sender.as_ref() else {
86	        return 0;
87	    };
88	    let registrations = match store::list_registrations(&state.db, did).await {
89	        Ok(rows) => rows,
90	        Err(e) => {
91	            tracing::warn!(error = %e, "failed to load notification registrations");
92	            return 0;
93	        }
94	    };
95	    fan_out(state, sender, registrations, payload, |device_id| {
96	        RegistrationOwner::Account {
97	            did: did.to_string(),
98	            device_uuid: device_id,
99	        }
100	    })
101	    .await
102	}
