130	/// Seal-and-enqueue one payload per registration, returning how many jobs were enqueued.
131	async fn fan_out(
132	    state: &AppState,
133	    sender: &crate::notify_relay_client::NotifySender,
134	    registrations: Vec<store::RegistrationRow>,
135	    payload: NotificationPayload,
136	    owner_of: impl Fn(String) -> RegistrationOwner,
137	) -> usize {
138	    if registrations.is_empty() {
139	        return 0;
140	    }
141	
142	    // Load the sealing key once for the whole fan-out. Doing it per device would mean a
143	    // rotation landing mid-fan-out seals some devices under the old key and some under the
144	    // new — both valid, but needlessly hard to reason about when debugging a delivery.
145	    let Some((kid, secret)) = active_sender_key(state).await else {
146	        return 0;
147	    };
148	
149	    let mut enqueued = 0;
150	    for registration in registrations {
151	        // A registration with no handle has not completed its relay round trip yet (the
152	        // relay was down at registration time, or the job is still queued). There is nothing
153	        // to push to; the next registration attempt mints one.
154	        let Some(handle) = registration.push_handle.clone() else {
155	            continue;
156	        };
157	
158	        let recipient =
159	            match crypto::p256_public_key_from_did_key(&registration.notification_public_key) {
160	                Ok(key) => key,
161	                Err(e) => {
162	                    // Registration validated this key, so reaching here means the stored row is
163	                    // corrupt — worth an error, not a silent skip.
164	                    tracing::error!(error = %e, "stored notification public key is unusable");
165	                    continue;
166	                }
167	            };
168	
169	        let Some(sealed) = seal_for(kid, &secret, &recipient, &payload) else {
170	            continue;
171	        };
172	
173	        // `send` fails only once every receiver is gone, i.e. the worker has stopped. Not
174	        // worth a per-device log line.
175	        sender.send(NotifyJob::Push {
176	            owner: owner_of(registration.device_id),
177	            handle,
178	            kid,
179	            enc: base64url(&sealed.enc),
180	            ct: base64url(&sealed.ct),
181	        });
182	        enqueued += 1;
183	    }
184	    enqueued
185	}
