187	/// Pad, then seal, one payload for one recipient.
188	///
189	/// Returns `None` when the payload cannot be sent — which for v1 means only one thing: it is
190	/// too large for the top padding bucket. We refuse rather than degrade. Sending it unpadded
191	/// would leak the exact length that padding exists to hide, and truncating the body would
192	/// deliver a security notice that no longer says what happened; a dropped banner is the one
193	/// failure mode with no downside beyond the missed banner itself.
194	fn seal_for(
195	    kid: i64,
196	    sender_secret: &[u8; 32],
197	    recipient_public_key: &[u8],
198	    payload: &NotificationPayload,
199	) -> Option<crypto::SealedNotification> {
200	    let pad_len = pad_len_for(kid, payload)?;
201	
202	    let mut padded = payload.clone();
203	    padded.pad = " ".repeat(pad_len);
204	    let plaintext = match serde_json::to_vec(&padded) {
205	        Ok(bytes) => bytes,
206	        Err(e) => {
207	            tracing::error!(error = %e, "failed to serialize a notification payload");
208	            return None;
209	        }
210	    };
211	
212	    match crypto::seal_notification(sender_secret, recipient_public_key, &plaintext) {
213	        Ok(sealed) => Some(sealed),
214	        Err(e) => {
215	            tracing::error!(error = %e, "failed to seal a notification");
216	            None
217	        }
218	    }
219	}
220	
221	/// How many pad bytes make this payload's APNs body land on a bucket.
222	///
223	/// The buckets are defined on the **serialized APNs request body**, because that is the only
224	/// length anyone on the path actually measures. So this models the exact body the relay will
225	/// build (via the shared [`notify_relay::protocol::apns_envelope`]) and works backwards
226	/// through base64url expansion. Sealing is deterministic in length — ciphertext is plaintext
227	/// plus a 16-byte tag, and `enc` is always a 65-byte point — so this needs no trial seal.
228	fn pad_len_for(kid: i64, payload: &NotificationPayload) -> Option<usize> {
229	    let unpadded_plaintext_len = serde_json::to_vec(payload).ok()?.len();
230	    let unpadded_ct_len = unpadded_plaintext_len + AEAD_TAG_LEN;
231	
232	    // Placeholder strings of the right *length*: only the byte count reaches the arithmetic,
233	    // and JSON escaping never touches base64url's alphabet.
234	    let envelope = notify_relay::protocol::apns_envelope(
235	        kid as u32,
236	        &"A".repeat(crypto::base64url_len(P256_POINT_LEN)),
237	        &"A".repeat(crypto::base64url_len(unpadded_ct_len)),
238	    );
239	    let unpadded_serialized_len = serde_json::to_vec(&envelope).ok()?.len();
240	
241	    let pad = crypto::plaintext_pad_len(unpadded_ct_len, unpadded_serialized_len);
242	    if pad.is_none() {
243	        tracing::error!(
244	            serialized_len = unpadded_serialized_len,
245	            "refusing to send a notification too large for any padding bucket; \
246	             sending it unpadded would leak the length padding exists to hide"
247	        );
248	    }
249	    pad
250	}
251	
252	/// AES-GCM authentication tag, appended to every ciphertext.
253	const AEAD_TAG_LEN: usize = 16;
254	
255	/// Uncompressed SEC1 P-256 point — the fixed wire length of the HPKE encapsulated key.
256	const P256_POINT_LEN: usize = 65;
257	
258	/// The sender key to seal with, generating the instance's first one on demand.
259	///
260	/// Lazy generation rather than a startup step: an instance that has notifications configured
261	/// but never sends one should not mint key material, and the first send is the earliest
262	/// moment the key is genuinely needed.
263	async fn active_sender_key(state: &AppState) -> Option<(i64, Zeroizing<[u8; 32]>)> {
264	    let master_key = master_key(state)?;
265	
266	    let existing = match store::get_active_sender_key(&state.db).await {
267	        Ok(row) => row,
268	        Err(e) => {
269	            tracing::warn!(error = %e, "failed to load the notification sender key");
270	            return None;
271	        }
272	    };
273	
274	    if let Some(row) = existing {
275	        return match crypto::decrypt_secret_bytes(&row.secret_key_encrypted, master_key) {
276	            Ok(bytes) => to_scalar(&bytes).map(|scalar| (row.kid, scalar)),
277	            Err(e) => {
278	                tracing::error!(error = %e, kid = row.kid, "failed to unwrap a sender key");
279	                None
280	            }
281	        };
282	    }
283	
284	    generate_sender_key(state, master_key).await
285	}
