287	/// Mint, wrap, and store a fresh sender key.
288	pub(crate) async fn generate_sender_key(
289	    state: &AppState,
290	    master_key: &[u8; 32],
291	) -> Option<(i64, Zeroizing<[u8; 32]>)> {
292	    let keypair = match crypto::generate_p256_keypair() {
293	        Ok(keypair) => keypair,
294	        Err(e) => {
295	            tracing::error!(error = %e, "failed to generate a notification sender key");
296	            return None;
297	        }
298	    };
299	    // Stays in `Zeroizing` the whole way. The crypto crate deliberately hands back a wiped-on-
300	    // drop buffer, and copying out into a bare `[u8; 32]` would silently discard that — leaving
301	    // the instance's sender scalar in freed memory on every send.
302	    let secret = keypair.private_key_bytes.clone();
303	    let wrapped = match crypto::encrypt_secret_bytes(&*secret, master_key) {
304	        Ok(wrapped) => wrapped,
305	        Err(e) => {
306	            tracing::error!(error = %e, "failed to wrap a notification sender key");
307	            return None;
308	        }
309	    };
310	    match store::insert_sender_key(&state.db, &wrapped).await {
311	        Ok(kid) => {
312	            tracing::info!(kid, "generated a new notification sender key");
313	            Some((kid, secret))
314	        }
315	        Err(e) => {
316	            tracing::error!(error = %e, "failed to store a notification sender key");
317	            None
318	        }
319	    }
320	}
