322	/// The published sender-key set: `(kid, did:key)` for every key a device may verify against.
323	///
324	/// This is the re-pin surface both `sender-keys` routes serve. Generating the first key here
325	/// as well as on send matters for onboarding order: an app that fetches the set before the
326	/// instance has ever sent anything would otherwise pin an empty set and be unable to verify
327	/// the first notification it receives.
328	pub async fn published_sender_keys(state: &AppState) -> Result<Vec<(i64, String)>, SenderKeyError> {
329	    // No master key means no key can be minted *or* unwrapped, so the honest answer is an
330	    // error, not an empty set. Answering `200 {"keys": []}` would let a client conclude it has
331	    // successfully pinned nothing — and then fail to verify every notification it receives,
332	    // with only a server-side warning to explain it. This is a misconfiguration; it should be
333	    // as visible as one.
334	    let master_key = master_key(state).ok_or(SenderKeyError::NoMasterKey)?;
335	
336	    let mut rows = store::list_publishable_sender_keys(&state.db).await?;
337	    if rows.is_empty() {
338	        generate_sender_key(state, master_key).await;
339	        rows = store::list_publishable_sender_keys(&state.db).await?;
340	    }
341	
342	    let keys: Vec<(i64, String)> = rows
343	        .into_iter()
344	        .filter_map(|row| {
345	            // An individual row that will not unwrap is skipped rather than fatal: it is a
346	            // key this instance can no longer use, and dropping it from the published set is
347	            // exactly right — but it must not take the still-good keys down with it.
348	            let secret = crypto::decrypt_secret_bytes(&row.secret_key_encrypted, master_key)
349	                .ok()
350	                .and_then(|bytes| to_scalar(&bytes))
351	                .or_else(|| {
352	                    tracing::error!(kid = row.kid, "a stored sender key will not unwrap");
353	                    None
354	                })?;
355	            // Re-derive the public half rather than storing it: one stored secret cannot
356	            // disagree with a separately stored public key if there is no separately stored
357	            // public key.
358	            let keypair = crypto::p256_keypair_from_secret(&secret).ok()?;
359	            Some((row.kid, keypair.key_id.0))
360	        })
361	        .collect();
362	
363	    // One invariant at the exit rather than a guard per failure path: **never publish an empty
364	    // set**. Several routes lead here — lazy generation failed, every stored key is unusable,
365	    // or some future path — and they all end the same way for a client, which pins nothing and
366	    // then cannot verify a single notification it receives. Checking the result instead of each
367	    // cause means a new failure mode is covered the day it appears.
368	    if keys.is_empty() {
369	        return Err(SenderKeyError::NoUsableKey);
370	    }
371	    Ok(keys)
372	}
373	
374	/// Why the published sender-key set could not be produced.
375	#[derive(Debug, thiserror::Error)]
376	pub enum SenderKeyError {
377	    #[error("notifications are configured but no signing-key master key is set")]
378	    NoMasterKey,
379	    /// A key could neither be minted nor unwrapped. Distinct from [`Self::NoMasterKey`] because
380	    /// the operator fix differs: the master key is present, so this is a generation failure or
381	    /// key material that no longer decrypts under it (both already logged with their cause).
382	    #[error("no usable notification sender key could be produced")]
383	    NoUsableKey,
384	    #[error(transparent)]
385	    Db(#[from] sqlx::Error),
386	}
