388	/// The master KEK, if configured. Callers report its absence — logging here would emit a line
389	/// per request on the read path, where the caller already turns it into a visible error.
390	fn master_key(state: &AppState) -> Option<&[u8; 32]> {
391	    state.config.signing_key_master_key.as_ref().map(|s| &*s.0)
392	}
393	
394	/// Narrow a decrypted secret to a 32-byte scalar without leaving `Zeroizing`.
395	///
396	/// `decrypt_secret_bytes` returns a `Zeroizing<Vec<u8>>`; converting through a bare array
397	/// would drop the wipe-on-drop guarantee for the copy, so the result is re-wrapped instead.
398	fn to_scalar(bytes: &[u8]) -> Option<Zeroizing<[u8; 32]>> {
399	    <[u8; 32]>::try_from(bytes).ok().map(Zeroizing::new)
400	}
401	
402	fn base64url(bytes: &[u8]) -> String {
403	    data_encoding::BASE64URL_NOPAD.encode(bytes)
404	}
