40	/// An offline endpoint on loopback (`Minimal` preset: rustls only — no relay, no discovery),
41	/// so the whole test runs with no network.
42	async fn loopback_endpoint(accepts: bool) -> Endpoint {
43	    let mut builder = Endpoint::builder(presets::Minimal)
44	        .bind_addr("127.0.0.1:0")
45	        .expect("valid bind addr");
46	    if accepts {
47	        builder = builder.alpns(vec![ALPN.to_vec()]);
48	    }
49	    builder.bind().await.expect("bind loopback endpoint")
50	}
