52	/// A real `notify-relay` wired to a stand-in Apple, with open enrollment.
53	async fn start_relay(
54	    apple_uri: &str,
55	) -> (
56	    Endpoint,
57	    Arc<notify_relay::service::RelayService>,
58	    tempfile::TempDir,
59	) {
60	    use notify_relay::config::load_from_env_only;
61	
62	    // The relay needs a real PKCS#8 P-256 key on disk to mint its APNs provider JWT. Generate
63	    // one rather than vendoring a fixture: the JWT is signed and sent, and wiremock accepts
64	    // any bearer, so the only requirement is that it is a genuine key.
65	    let dir = tempfile::tempdir().expect("tempdir");
66	    let key_path = dir.path().join("apns.p8");
67	    let signing_key = p256::ecdsa::SigningKey::random(&mut rand_core::OsRng);
68	    let pem = p256::pkcs8::EncodePrivateKey::to_pkcs8_pem(
69	        &p256::SecretKey::from(&signing_key),
70	        p256::pkcs8::LineEnding::LF,
71	    )
72	    .expect("encode PKCS#8");
73	    std::fs::write(&key_path, pem.as_bytes()).expect("write APNs key");
74	
75	    let env = std::collections::HashMap::from([
76	        ("EZPDS_NOTIFY_OPEN_ENROLLMENT".to_owned(), "true".to_owned()),
77	        (
78	            "EZPDS_NOTIFY_APNS_KEY_PATH".to_owned(),
79	            key_path.display().to_string(),
80	        ),
81	        (
82	            "EZPDS_NOTIFY_APNS_KEY_ID".to_owned(),
83	            "KEYID12345".to_owned(),
84	        ),
85	        (
86	            "EZPDS_NOTIFY_APNS_TEAM_ID".to_owned(),
87	            "TEAM123456".to_owned(),
88	        ),
89	        ("EZPDS_NOTIFY_APNS_URL".to_owned(), apple_uri.to_owned()),
90	    ]);
91	    let config = Arc::new(load_from_env_only(&env).expect("relay config"));
92	
93	    let pool = notify_relay::db::open_pool("sqlite::memory:")
94	        .await
95	        .expect("relay pool");
96	    notify_relay::db::run_migrations(&pool)
97	        .await
98	        .expect("relay migrations");
99	
100	    let apns = notify_relay::apns::ApnsClient::new(&config.apns).expect("APNs client");
101	    assert!(apns.is_some(), "the test relay must have APNs credentials");
102	
103	    let service = Arc::new(notify_relay::service::RelayService::new(pool, config).with_apns(apns));
104	    let endpoint = loopback_endpoint(true).await;
105	    notify_relay::transport::spawn_accept_loop(endpoint.clone(), Arc::clone(&service));
