113	    let mut config = (*state.config).clone();
114	    // A node id is required for the feature to be considered configured; the client dials
115	    // `relay_addr` directly, since loopback has no discovery to resolve this against.
116	    config.notifications.relay = Some(relay_addr.id.to_string());
117	    config.iroh.enabled = true;
