345	/// Phase C of wallet-confirmed OAuth consent, end to end on the server side: a login started
346	/// on another surface (`GET /oauth/authorize` with a `login_hint` naming a hosted account)
347	/// produces a sealed `login-approval` push through the real relay; the device opens it and
348	/// finds the routing data; the login page displays the mandatory match number; and the relay
349	/// and Apple see only the fixed placeholder — they never learn a login is happening.
350	#[tokio::test]
351	async fn a_hinted_login_pushes_a_sealed_login_approval_to_the_wallet() {
352	    let apple = MockServer::start().await;
353	    Mock::given(method("POST"))
354	        .respond_with(ResponseTemplate::new(200))
355	        .mount(&apple)
356	        .await;
357	
358	    let (relay_endpoint, _relay, _keydir) = start_relay(&apple.uri()).await;
359	    let relay_addr =
360	        EndpointAddr::new(relay_endpoint.id()).with_ip_addr(relay_endpoint.bound_sockets()[0]);
361	    let (state, dialer) = start_pds(relay_addr).await;
362	
363	    // A hosted, handle-bearing account with a registered wallet device.
364	    sqlx::query("INSERT INTO handles (handle, did, created_at) VALUES (?, ?, datetime('now'))")
365	        .bind("notifye2e.example.com")
366	        .bind(ACCOUNT_DID)
367	        .execute(&state.db)
368	        .await
369	        .expect("seed handle");
370	    let device = crypto::generate_p256_keypair().expect("device keypair");
371	    register_device(&state, &device.key_id.0).await;
372	    let (_kid, sender_public_key) = published_sender_key(&state).await;
373	
374	    // A registered OAuth client, and the login another device starts against it.
375	    crate::db::oauth::register_oauth_client(
376	        &state.db,
377	        "https://app.example.com/client-metadata.json",
378	        r#"{"redirect_uris":["https://app.example.com/callback"],"client_name":"Test App"}"#,
379	    )
380	    .await
381	    .expect("register client");
382	
383	    let response = crate::app::app(state.clone())
384	        .oneshot(
385	            Request::get(
386	                "/oauth/authorize\
387	                 ?client_id=https%3A%2F%2Fapp.example.com%2Fclient-metadata.json\
388	                 &redirect_uri=https%3A%2F%2Fapp.example.com%2Fcallback\
389	                 &code_challenge=e3b0c44298fc1c149afb\
390	                 &code_challenge_method=S256\
391	                 &state=teststate\
392	                 &response_type=code\
393	                 &scope=atproto\
394	                 &login_hint=notifye2e.example.com",
395	            )
396	            .body(Body::empty())
397	            .unwrap(),
398	        )
399	        .await
400	        .expect("consent page");
401	    assert_eq!(response.status(), StatusCode::OK);
402	    let html_bytes = axum::body::to_bytes(response.into_body(), 1 << 20)
403	        .await
404	        .expect("page body");
405	    let html = std::str::from_utf8(&html_bytes).expect("utf8 page");
406	
407	    // The pending row latched the match code, and the page displays that exact number.
408	    let (request_id, match_code): (String, String) = sqlx::query_as(
409	        "SELECT request_id, match_code FROM pending_oauth_authorizations WHERE match_code IS NOT NULL",
410	    )
411	    .fetch_one(&state.db)
412	    .await
413	    .expect("a push-dispatched pending row");
414	    assert!(
415	        html.contains(&format!(
416	            "<div class=\"match-code mono\" id=\"match-code\">{match_code}</div>"
417	        )),
418	        "the login surface must display the match number"
419	    );
420	
421	    // The push that crossed the wire: placeholder alert outside, `login-approval` inside.
422	    let body = await_condition("the pushed APNs body", || async {
423	        apple
424	            .received_requests()
425	            .await
426	            .unwrap_or_default()
427	            .into_iter()
428	            .find_map(|req| serde_json::from_slice::<serde_json::Value>(&req.body).ok())
429	    })
430	    .await;
431	    assert_eq!(body["aps"]["alert"]["title"], "Custos");
432	    assert_eq!(body["aps"]["alert"]["body"], "Encrypted notification");
433	
434	    let decode = |field: &str| {
435	        data_encoding::BASE64URL_NOPAD
436	            .decode(body["ezpds"][field].as_str().expect("string").as_bytes())
437	            .expect("base64url")
438	    };
439	    let plaintext = crypto::open_notification(
440	        &device.private_key_bytes,
441	        &sender_public_key,
442	        &decode("enc"),
443	        &decode("ct"),
444	    )
445	    .expect("the device must open the login-approval payload");
446	    let opened: serde_json::Value = serde_json::from_slice(&plaintext).expect("payload JSON");
447	    assert_eq!(opened["type"], "login-approval");
448	    assert_eq!(opened["data"]["requestId"], request_id.as_str());
449	    assert_eq!(opened["data"]["did"], ACCOUNT_DID);
450	    assert_eq!(opened["data"]["clientName"], "Test App");
451	    // The match number must never ride in the push — it is the proof the approver can see the
452	    // login surface, so handing it to the wallet would defeat the channel binding. (Asserted on
