/// registration claims.
pub async fn set_registration_handles_for_token(
    pool: &SqlitePool,
    apns_token: &str,
    push_handle: &str,
) -> Result<u64, sqlx::Error> {
    let result = sqlx::query(
        "UPDATE notification_registrations SET push_handle = ?, updated_at = datetime('now') \
         WHERE apns_token = ?",
    )
    .bind(push_handle)
    .bind(apns_token)
    .execute(pool)
    .await?;
    Ok(result.rows_affected())
}

